<?php require __DIR__.'/config.php'; $error=$_GET['error']??''; ?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ورود | APEX TS</title><link rel="stylesheet" href="assets/style.css"></head><body class="auth-page"><a class="back" href="index.php">← بازگشت</a><div class="auth-card"><div class="eyebrow">APEX ACCOUNT</div><h1>ورود / ثبت‌نام</h1><?php if($error):?><div class="error"><?=e($error)?></div><?php endif;?><div class="tabs"><button onclick="tab('login')">ورود</button><button onclick="tab('signup')">ثبت‌نام</button></div><form id="login" action="auth.php" method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="login"><label>نام کاربری یا ایمیل<input name="login" required></label><label>رمز عبور<input type="password" name="password" required></label><button class="btn primary full">ورود</button></form><form id="signup" class="hidden" action="auth.php" method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="signup"><label>نام کاربری<input name="username" pattern="[A-Za-z0-9_]{3,50}" required></label><label>ایمیل<input type="email" name="email" required></label><label>رمز عبور<input type="password" name="password" minlength="8" required></label><button class="btn primary full">ساخت حساب</button></form></div><script>function tab(x){document.getElementById('login').classList.toggle('hidden',x!=='login');document.getElementById('signup').classList.toggle('hidden',x!=='signup')}</script></body></html>
